begin
  with points as (
    select ordinality as idx, (point->>'lat')::double precision as lat,
      (point->>'lon')::double precision as lon
    from jsonb_array_elements(v_segments->0) with ordinality as p(point, ordinality)
  ), steps as (
    select lat, lon, lag(lat) over (order by idx) as prev_lat,
      lag(lon) over (order by idx) as prev_lon from points
  ), lengths as (
    select case when prev_lat is null then 0 else 6371 * 2 * asin(sqrt(
      power(sin(radians(lat-prev_lat)/2),2) +
      cos(radians(prev_lat))*cos(radians(lat))*
      power(sin(radians(lon-prev_lon)/2),2)
    )) end as km from steps
  )
  select count(*), sum(km), max(km)
  into v_count, v_length_km, v_max_gap_km from lengths;

  if v_count <> 449 or v_length_km not between 8.2 and 8.5
    or v_max_gap_km > 0.1 then
    raise exception 'Official track failed continuity check';
  end if;
  if not exists (
    select 1 from public.hiking_routes h
    join public.hiking_route_regions m on m.route_id=h.id and m.published
    where h.id='osm-relation-15720833' and h.source='openstreetmap'
      and h.province='Guadalajara'
  ) then
    raise exception 'Official track route or published region missing';
  end if;

  insert into public.hiking_route_tracks
    (route_id,status,segments,checked_at,continuity_checked,
     geometry_source,geometry_source_url,official)
  values ('osm-relation-15720833','ready',v_segments,now(),true,
    'Red de Áreas Protegidas de Castilla-La Mancha',
    'https://medionatural.castillalamancha.es/sites/default/files/kml//pn_senda_del_castillo_de_valtablado.gpx',
    true)
  on conflict (route_id) do update set
    status=excluded.status,segments=excluded.segments,
    checked_at=excluded.checked_at,continuity_checked=true,
    geometry_source=excluded.geometry_source,
    geometry_source_url=excluded.geometry_source_url,official=true;

  update public.hiking_routes set trace_available=true,published=true,
    official_url='https://medionatural.castillalamancha.es/rap/espacios-naturales-protegidos/enp-parque-natural/parque-natural-del-alto-tajo/rutas/sendero-2-senda-del-castillo-de-valtablado'
  where id='osm-relation-15720833';
end
$curate$;
